    static let REMOVALS: VOffset = 22
    static let URLS: VOffset = 24
    static let SIGNATURES: VOffset = 26
    static let SEALED: VOffset = 28
    static let IDENTITIES: VOffset = 30
    static let LARGE: VOffset = 32
