  ///  Stream offset of the previous non-record frame (the commit chain).
  public var PREVIOUS: UInt64 { let o = _accessor.offset(VT.PREVIOUS); return o == 0 ? 0 : _accessor.readBuffer(of: UInt64.self, at: o) }
  ///  The feed's id in its type.
